// Styling for the Contact page.
//
// Two columns that read as one composition: the invitation and the details on
// the left, the form on the right. They share a baseline and the same vertical
// rhythm so the page does not look like two panels that happened to land beside
// each other.
//
// The form panel is a tonal shift plus a thin border rather than a shadowed
// card. That is the treatment the rest of this site uses, and a floating card
// here would be the one shadow on the whole website.

import template1 from "./template-1";

export type ContactTemplate = {
  css: string;
  rootClass: string;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-contact {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
}
.kr-contact__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.introColumn} ${layout.formColumn};
  align-items: start;
  gap: ${spacing.columnGap}px;
}

/* ── the invitation ───────────────────────────────────── */
.kr-contact__intro { min-width: 0; }

.kr-contact__eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;
}
.kr-contact__eyebrow::before {
  content: "";
  width: ${layout.ruleWidth}px;
  height: ${layout.ruleHeight}px;
  flex-shrink: 0;
  background: ${color.rule};
}

.kr-contact__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
}

.kr-contact__lede {
  margin: 0 0 ${spacing.ledeGap}px;
  color: ${color.lede};
  font-family: ${typography.ledeFamily};
  font-size: ${typography.ledeSize};
  font-weight: ${typography.ledeWeight};
  line-height: ${typography.ledeLeading};
}

/* ── the details ──────────────────────────────────────── */
.kr-contact__details {
  display: grid;
  gap: ${spacing.detailGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-contact__detail {
  display: flex;
  align-items: flex-start;
  gap: ${spacing.detailIconGap}px;
  min-width: 0;
}
.kr-contact__detail-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: ${layout.detailIconSize}px;
  height: ${layout.detailIconSize}px;
  flex-shrink: 0;
  border-radius: 50%;
  background: ${color.detailIconBackground};
  color: ${color.detailIcon};
}
.kr-contact__detail-label {
  display: block;
  margin-bottom: ${spacing.detailLabelGap}px;
  color: ${color.detailLabel};
  font-family: ${typography.detailLabelFamily};
  font-size: ${typography.detailLabelSize}px;
  font-weight: ${typography.detailLabelWeight};
  letter-spacing: ${typography.detailLabelTracking};
  text-transform: uppercase;
}
.kr-contact__detail-value {
  display: block;
  min-width: 0;
  color: ${color.detailValue};
  font-family: ${typography.detailValueFamily};
  font-size: ${typography.detailValueSize};
  font-weight: ${typography.detailValueWeight};
  word-break: break-word;
}
/* Phone and email are links; location and hours are not. Both look the same
   until you hover, which is correct — the difference is what they DO. */
a.kr-contact__detail-value {
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
a.kr-contact__detail-value:hover { color: ${color.detailValueHover}; }
a.kr-contact__detail-value:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 3px;
}

/* ── the aside under the details ──────────────────────── */
.kr-contact__aside {
  margin-top: ${spacing.asideTop}px;
  padding: ${spacing.asidePadding}px;
  background: ${color.asideBackground};
  border: 1px solid ${color.asideBorder};
  border-radius: ${layout.radius}px;
}
.kr-contact__aside-title {
  margin: 0 0 ${spacing.asideTitleGap}px;
  color: ${color.asideTitle};
  font-family: ${typography.asideTitleFamily};
  font-size: ${typography.asideTitleSize}px;
  font-weight: ${typography.asideTitleWeight};
  letter-spacing: ${typography.asideTitleTracking};
}
.kr-contact__aside-text {
  margin: 0 0 ${spacing.asideTextGap}px;
  color: ${color.asideText};
  font-family: ${typography.asideTextFamily};
  font-size: ${typography.asideTextSize}px;
  font-weight: ${typography.asideTextWeight};
  line-height: ${typography.asideTextLeading};
}

/* ── the form panel ───────────────────────────────────── */
.kr-contact__panel {
  min-width: 0;
  padding: ${spacing.panelPadding}px;
  background: ${color.panelBackground};
  border: 1px solid ${color.panelBorder};
  border-radius: ${layout.radius}px;
}
.kr-contact__panel-title {
  margin: 0 0 ${spacing.panelTitleGap}px;
  color: ${color.panelTitle};
  font-family: ${typography.panelTitleFamily};
  font-size: ${typography.panelTitleSize};
  font-weight: ${typography.panelTitleWeight};
  letter-spacing: ${typography.panelTitleTracking};
}
.kr-contact__panel-text {
  margin: 0 0 ${spacing.panelTextGap}px;
  color: ${color.panelText};
  font-family: ${typography.panelTextFamily};
  font-size: ${typography.panelTextSize}px;
  font-weight: ${typography.panelTextWeight};
  line-height: ${typography.panelTextLeading};
}

/* ── the shared form's own wrappers ─────────────────────
   GForm styles its fields inline from application-form--template, so the only
   thing left to place is the small print and the success state. Both are
   scoped inside the panel so nothing here can reach the apply page, which
   styles the same two classes its own way. */
.kr-contact__panel .kr-apply__note {
  margin: 22px 0 0;
  color: ${color.panelText};
  font-family: ${typography.panelTextFamily};
  font-size: 12.5px;
  line-height: 1.7;
}
.kr-contact__panel .kr-apply__success {
  padding: 28px 0 12px;
  text-align: left;
}
.kr-contact__panel .kr-apply__success-icon {
  display: inline-flex;
  margin-bottom: 14px;
  color: ${color.detailIcon};
}
.kr-contact__panel .kr-apply__success-title {
  margin: 0 0 10px;
  color: ${color.panelTitle};
  font-family: ${typography.panelTitleFamily};
  font-size: 21px;
  font-weight: ${typography.panelTitleWeight};
  letter-spacing: -0.02em;
}
.kr-contact__panel .kr-apply__success-text {
  margin: 0;
  max-width: 46ch;
  color: ${color.panelText};
  font-family: ${typography.panelTextFamily};
  font-size: 14.5px;
  line-height: 1.7;
}

/* ── narrow screens ───────────────────────────────────── */
@media (max-width: ${layout.stackBelow}px) {
  .kr-contact {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-contact__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
    padding: 0 ${spacing.gutterCompact}px;
  }
  /* The panel loses its inset on a phone so the inputs keep their full width
     rather than being squeezed by two lots of padding. */
  .kr-contact__panel { padding: ${spacing.panelPaddingCompact}px; }
}

@media (prefers-reduced-motion: reduce) {
  a.kr-contact__detail-value { transition-duration: .01ms; }
}
`;

const template: ContactTemplate = {
  css,
  rootClass: "kr-contact",
};

export default template;
