// @ppm--version--1.0
//
// Turns one decrypted submission into the Lead the UI renders.
//
// VERIFIED SHAPE (all 9 records in the live repo, keys plaintext / values
// individually encrypted):
//
//   { submissionId, name, phone, email, message, siteId, tag,
//     mappings: { submissionId, name, phone, email, message, siteId, form } }
//
// `mappings` is the writer's own field-name table (e.g. siteId -> "site_id").
// It is metadata, not lead content, so only `mappings.form` — the identifier of
// the form that produced the submission — is carried through.
//
// Field lookups keep a short alias list: the live data is camelCase, but the
// mappings table advertises snake_case names, so a writer change to that
// convention would otherwise silently blank every column.

import type { Lead } from "./types";

/** First alias present on the record, as a trimmed string. */
function pick(record: Record<string, unknown>, aliases: string[]): string {
  for (const alias of aliases) {
    const value = record[alias];

    if (typeof value === "string" && value.trim()) return value.trim();
    if (typeof value === "number") return String(value);
  }

  return "";
}

/** `1788077388994.json` -> 1788077388994. NaN-safe. */
export function receivedAtFromFilename(filename: string): number {
  const timestamp = Number(filename.replace(/\.json$/i, ""));

  return Number.isFinite(timestamp) ? timestamp : 0;
}

export function normalizeLead(
  filename: string,
  record: Record<string, unknown>
): Lead {


  const mappings =
    record.mappings && typeof record.mappings === "object" && !Array.isArray(record.mappings)
      ? (record.mappings as Record<string, unknown>)
      : {};

  const id = pick(record, ["submissionId", "submission_id", "id"]);

  const lead: Lead = {
    // The filename is unique per submission, so it is a sound fallback id.
    id: id || filename,
    name: pick(record, ["name", "fullName", "full_name"]),
    phone: pick(record, ["phone", "phoneNumber", "phone_number"]),
    email: pick(record, ["email", "emailAddress", "email_address"]),
    receivedAt: receivedAtFromFilename(filename),
  };

  const message = pick(record, ["message", "body", "notes"]);
  const siteId = pick(record, ["siteId", "site_id"]);
  const tag = pick(record, ["tag", "tags"]);
  const form = pick(record, ["form", "formId", "form_id"]) || pick(mappings, ["form"]);

  if (message) lead.message = message;
  if (siteId) lead.siteId = siteId;
  if (tag) lead.tag = tag;
  if (form) lead.form = form;

  // `status` is intentionally absent: submissions carry no such field. The UI
  // renders an em dash for it until the source (or the CMS) supplies one.

  return lead;
}
