// Use Supabase as the CMS backend.
//
// TRUE  — applications, properties, leads and images read and write to the
//         Supabase project named in config/supabase--url.ts.
// FALSE — the CMS falls back to whatever toggles/demo-local-storage says:
//         browser-local demo storage, or the older worker adapters.
//
// The switch only takes effect when the project URL and anon key are both
// filled in; an unconfigured Supabase would otherwise fail every call and look
// like a broken CMS rather than an unfinished one. See modules/supabase/client.
export default true;
