import React from "react";
import { Link } from "gatsby";

import type { ContactTemplate } from "../../templates/contact/default-template";
import type { ContactContent } from "./types";

export type ContactProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: ContactTemplate;
  content: ContactContent;
  /** The form itself, composed by the primitive so this stays presentational. */
  form: React.ReactNode;
  enabled?: boolean;
};

/**
 * The Contact page.
 *
 * Two halves of one composition: what you can reach us with on the left, and
 * the means of doing it on the right. The form is passed in rather than built
 * here — it is the site's shared form engine, and this component should not
 * know how a submission works any more than it knows how a phone call does.
 */
export default function Contact({
  template,
  content,
  form,
  enabled = true,
}: ContactProps) {
  if (!enabled) return null;

  const root = template.rootClass;

  return (
    <section className={root} aria-labelledby="kr-contact-title">
      <style>{template.css}</style>

      <div className={`${root}__inner`}>
        <div className={`${root}__intro`}>
          <p className={`${root}__eyebrow`}>{content.eyebrow}</p>

          <h1 className={`${root}__title`} id="kr-contact-title">
            {content.title}
          </h1>

          <p className={`${root}__lede`}>{content.lede}</p>

          <ul className={`${root}__details`}>
            {content.details.map((detail) => {
              const Icon = detail.icon;

              return (
                <li key={detail.label} className={`${root}__detail`}>
                  <span className={`${root}__detail-icon`} aria-hidden="true">
                    <Icon size={16} strokeWidth={1.5} />
                  </span>

                  <span>
                    <span className={`${root}__detail-label`}>{detail.label}</span>

                    {detail.href ? (
                      <a className={`${root}__detail-value`} href={detail.href}>
                        {detail.value}
                      </a>
                    ) : (
                      <span className={`${root}__detail-value`}>{detail.value}</span>
                    )}
                  </span>
                </li>
              );
            })}
          </ul>

          <div className={`${root}__aside`}>
            <h2 className={`${root}__aside-title`}>{content.aside.title}</h2>
            <p className={`${root}__aside-text`}>{content.aside.text}</p>
            <Link className="kr-btn kr-btn--outline kr-btn--sm" to={content.aside.action.to}>
              {content.aside.action.label}
            </Link>
          </div>
        </div>

        <div className={`${root}__panel`}>
          <h2 className={`${root}__panel-title`}>{content.form.title}</h2>
          <p className={`${root}__panel-text`}>{content.form.text}</p>
          {form}
        </div>
      </div>
    </section>
  );
}
