import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import Layout from "../components/Layout";
import ContactX from "../ppm/primitives/contact/contact-x";

/**
 * Contact.
 *
 * The contact details are not written here or on the page component — they
 * come from config/profile--contact, which the header and footer already read,
 * so the site can never end up giving two different phone numbers.
 */
export default function ContactPage(_props: PageProps) {
  return (
    <Layout>
      <ContactX />
    </Layout>
  );
}

export const Head: HeadFC = () => (
  <>
    <title>Contact | Kelley Road Property Management</title>
    <meta
      name="description"
      content="Get in touch with Kelley Road Property Management about renting a home, a property you already rent, or a management enquiry."
    />
  </>
);
