// Whether this site is actually running on Supabase.
//
// TWO things have to be true, and keeping them separate matters:
//
//   the toggle          somebody intends to use Supabase
//   supabaseConfigured  the project URL and anon key are actually filled in
//
// A site with the toggle on and no keys is the dangerous case. Every request
// would fail, every screen would show an error, and it would read to the
// client as a broken CMS rather than an unfinished setup. So an unconfigured
// project falls back to demo storage and says so, exactly as it does today.
//
// Nothing else in the codebase asks the toggle directly. This is the one
// answer, so a half-configured project cannot be on in one module and off in
// another.

import supabaseToggle from "../../toggles/supabase.ts";
import { supabaseConfigured } from "./client.ts";

export const usingSupabase = (): boolean =>
  supabaseToggle && supabaseConfigured();
