import React from "react";
import { LuClock, LuMail, LuMapPin, LuPhone } from "react-icons/lu";

import formTemplate from "../../config/application-form--template";
import template from "../../config/contact--template";
import { publickey } from "../../config/gforms--publickey";
import {
  EMAIL,
  EMAIL_HREF,
  HOURS,
  LOCATION,
  PHONE_DISPLAY,
  PHONE_HREF,
} from "../../config/profile--contact";
import ApplicationForm from "../../modules/application/ApplicationForm";
import Contact from "../../modules/contact/Contact";
import type { ContactContent } from "../../modules/contact/types";
import type { GFormField } from "../../modules/gh-leads/GForm";
import {
  requiresPublicKey,
  useHandleSubmitForm,
} from "../../modules/gforms/handleSubmitForm";
import contactEnabled from "../../toggles/contact";

/**
 * The contact form, as data.
 *
 * Five fields, which is the whole point: this is a way to start a conversation,
 * not an application. Anything that belongs on the application form stays on
 * the application form, and the aside beside this points people there.
 *
 * Editing this array IS editing the form — no markup, no validation code. The
 * shared GForm renderer supplies the labels, the required marks, the error
 * messages and the focus behaviour.
 */
export const contactFields: GFormField[] = [
  {
    name: "fullName",
    type: "text",
    label: "Your Name",
    placeholder: "Your full name",
    required: true,
  },
  {
    name: "email",
    type: "email",
    label: "Email Address",
    placeholder: "you@example.com",
    required: true,
  },
  {
    name: "phone",
    type: "tel",
    label: "Phone Number",
    placeholder: "(208) 000-0000",
  },
  {
    name: "reason",
    type: "select",
    label: "What Is This About?",
    placeholder: "Select a reason",
    required: true,
    /* Neutral categories only. None of these promises a service, a response
       time or a process that has not been agreed with the client. */
    options: [
      { label: "Renting a property", value: "renting" },
      { label: "A property I already rent", value: "current-resident" },
      { label: "Property management enquiry", value: "management" },
      { label: "Something else", value: "other" },
    ],
  },
  {
    name: "message",
    type: "textarea",
    label: "Message",
    placeholder: "Tell us how we can help.",
    rows: 6,
    required: true,
  },
];

/**
 * Contact — content.
 *
 * The contact DETAILS are not written here. They are read from
 * config/profile--contact.ts, which the header and footer already use, so
 * changing the phone number in one place changes it everywhere. Duplicating
 * them onto this page would guarantee that one day the footer and the contact
 * page disagree about how to reach the same business.
 *
 * Those values are currently the client's TODO placeholders — a 555 number and
 * a generic mailbox. That is a content gap to be filled once, in that file,
 * not a reason for this page to invent its own.
 */
const content: ContactContent = {
  eyebrow: "Contact",

  title: "Talk to us about your property.",

  lede:
    "Whether you are looking for somewhere to live, already renting with us, " +
    "or have a property of your own to discuss — send a message and the team " +
    "will come back to you.",

  details: [
    { label: "Phone", value: PHONE_DISPLAY, href: PHONE_HREF, icon: LuPhone },
    { label: "Email", value: EMAIL, href: EMAIL_HREF, icon: LuMail },
    { label: "Where we are", value: LOCATION, icon: LuMapPin },
    { label: "Office hours", value: HOURS, icon: LuClock },
  ],

  aside: {
    title: "Ready to apply?",
    text:
      "If you already know which home you would like, the application form " +
      "asks for everything we need in one go.",
    action: { label: "Apply Now", to: "/apply" },
  },

  form: {
    title: "Send us a message",
    /* Not "fields marked with an asterisk" — the shared form renders no
       asterisk, and telling somebody to look for a mark that is not there is
       worse than saying nothing. */
    text: "Tell us what you need and we will come back to you.",
  },
};

/**
 * The Contact page, configured.
 *
 * Submission goes through the site's existing handler, which encrypts the
 * values with the site's public key before they leave the browser — the same
 * path the application form uses. There is deliberately no second backend.
 *
 * That key is still an unfilled placeholder, so rather than showing a tick and
 * dropping somebody's enquiry on the floor, the form refuses and says what to
 * do instead. The message goes to the form's own error slot, in plain language,
 * with no mention of keys, workers or repositories.
 */
export default function ContactX() {
  const { handleSubmitForm } = useHandleSubmitForm();

  const onSubmit = async (values: Record<string, unknown>) => {
    /* Only the encrypting transport needs a key. Supabase does not, and
       demanding one there would refuse a form that works perfectly. */
    if (requiresPublicKey() && (!publickey || !publickey.trim())) {
      throw new Error(
        `This form is not connected yet. Please call us on ${PHONE_DISPLAY} or email ${EMAIL} and we will pick it up from there.`
      );
    }

    /* The shared handler RETURNS a failure rather than throwing one, and the
       form shows its success screen for anything that does not throw. So a
       dropped connection would tell somebody their message was sent when it
       was not. Checked here rather than patched into the shared handler,
       which the application form also depends on. */
    const outcome = await handleSubmitForm(values, publickey);

    if (outcome && outcome.success === false) {
      throw new Error(
        `Your message could not be sent — the connection failed. Please try again, or call us on ${PHONE_DISPLAY}.`
      );
    }
  };

  if (!contactEnabled) return null;

  return (
    <Contact
      template={template}
      content={content}
      form={
        <ApplicationForm
          fields={contactFields}
          formTemplate={formTemplate}
          submitLabel="Send Message"
          submittingLabel="Sending…"
          note="We will use your details to reply to this enquiry."
          /* The shared form defaults to the APPLICATION wording. Somebody who
             asked a question should not be told their application was
             received — the message has to match what they actually sent. */
          successTitle="Message sent"
          successText="Thank you for getting in touch. A member of the Kelley Road team will reply to you shortly."
          onSubmit={onSubmit}
        />
      }
    />
  );
}
